class MetricsCalculator:
    PASS = 1
    FAIL = 0

    def __init__(self):
        self._true_positives = 0
        self._false_positives = 0
        self._false_negatives = 0
        self._true_negatives = 0

    @property
    def true_positives(self):
        return self._true_positives

    @true_positives.setter
    def true_positives(self, value):
        self._true_positives = value

    @property
    def false_positives(self):
        return self._false_positives

    @false_positives.setter
    def false_positives(self, value):
        self._false_positives = value

    @property
    def false_negatives(self):
        return self._false_negatives

    @false_negatives.setter
    def false_negatives(self, value):
        self._false_negatives = value

    @property
    def true_negatives(self):
        return self._true_negatives

    @true_negatives.setter
    def true_negatives(self, value):
        self._true_negatives = value

    def _increment_counter(self, counter_name):
        setattr(self, f'_{counter_name}', getattr(self, f'_{counter_name}') + 1)

    def update(self, predicted_labels, true_labels):
        for predicted, true in zip(predicted_labels, true_labels):
            if predicted == self.PASS:
                if true == self.PASS:
                    self._increment_counter('true_positives')
                else:
                    self._increment_counter('false_positives')
            elif true == self.PASS:
                self._increment_counter('false_negatives')
            else:
                self._increment_counter('true_negatives')

    def precision(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        denominator = self.true_positives + self.false_positives
        if denominator == 0:
            return 0.0
        return self.true_positives / denominator

    def recall(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        denominator = self.true_positives + self.false_negatives
        if denominator == 0:
            return 0.0
        return self.true_positives / denominator

    def f1_score(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        precision = self._compute_precision()
        recall = self._compute_recall()
        if precision + recall == 0.0:
            return 0.0
        return (2 * precision * recall) / (precision + recall)

    def accuracy(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        total = self._total_samples()
        if total == 0:
            return 0.0
        return (self.true_positives + self.true_negatives) / total

    def _compute_precision(self):
        denominator = self.true_positives + self.false_positives
        if denominator == 0:
            return 0.0
        return self.true_positives / denominator

    def _compute_recall(self):
        denominator = self.true_positives + self.false_negatives
        if denominator == 0:
            return 0.0
        return self.true_positives / denominator

    def _total_samples(self):
        return self.true_positives + self.true_negatives + self.false_positives + self.false_negatives
